// getCISummary computes CI check state counts from status checks.
// Checks with empty names (GitHub summary checks) are excluded.
func getCISummary(checks []StatusCheckRun) CISummary {
	var s CISummary
	for _, c := range checks {
		if c.Name == "" {
			continue
		}
		s.Total++
		switch c.Result() {
		case "pass":
			s.Pass++
		case "fail":
			s.Fail++
		default:
			s.Pending++
		}
	}
	return s
}

